import UPlot, { Options as UPlotOptions, AlignedData as UPlotData, Series, SyncPubSub } from 'uplot';
import LegendPlugin from './plugins/legend/legend';
import { TooltipPlugin } from './plugins/tooltip/tooltip';
import cursorPlugin from './plugins/cursor/cursor';
import { PlotLinesPlugin } from './plugins/plotLines/plotLines';
import { YagrConfig, RawSerieData, MinimalValidConfig, YagrTheme } from './types';
import ColorParser from './utils/colors';
import ThemedDefaults from './defaults';
import i18n from './locale';
export interface YagrEvent {
    chart: Yagr;
    meta: YagrMeta;
}
export declare type YagrMeta = {
    renderTime: number;
    processTime: number;
    initTime: number;
};
export interface YagrState {
    isMouseOver: boolean;
    stage: 'config' | 'processing' | 'uplot' | 'render' | 'listen';
    inBatch?: boolean;
}
export interface UpdateOptions {
    incremental?: boolean;
    splice?: boolean;
}
declare class Yagr<TConfig extends MinimalValidConfig = MinimalValidConfig> {
    id: string;
    options: UPlotOptions;
    uplot: UPlot;
    root: HTMLElement;
    series: UPlotData;
    config: YagrConfig;
    resizeOb?: ResizeObserver;
    canvas: HTMLCanvasElement;
    plugins: {
        tooltip?: ReturnType<TooltipPlugin>;
        plotLines?: ReturnType<PlotLinesPlugin>;
        cursor?: ReturnType<typeof cursorPlugin>;
        legend?: LegendPlugin;
    } & (TConfig['plugins'] extends YagrConfig['plugins'] ? {
        [key in keyof TConfig['plugins']]: ReturnType<TConfig['plugins'][key]>;
    } : {});
    state: YagrState;
    utils: {
        colors: ColorParser;
        sync?: SyncPubSub;
