import Yagr, {MinimalValidConfig, YagrTheme} from 'yagr';
import 'yagr/dist/index.css';

export type ChartTheme = 'light' | 'dark';

export interface CpuChartHandle {
  /** Append new samples, dropping the oldest ones (sliding window). */
  append(times: number[], values: (number | null)[]): void;
}

interface Props {
  theme: ChartTheme;
  timeline: number[];
  values: (number | null)[];
}

const SERIES_ID = 'cpu';

