  light: {line: '#2a78d6', fill: 'rgba(42, 120, 214, 0.16)'},
  dark: {line: '#3987e5', fill: 'rgba(57, 135, 229, 0.24)'},
};

function buildConfig(theme, timeline, values): MinimalValidConfig { ... }

export const CpuChart = forwardRef<CpuChartHandle, Props>(({theme, timeline, values}, ref) => {
  const rootRef = useRef<HTMLDivElement>(null);
  const chartRef = useRef<Yagr | null>(null);

  // create once
  useEffect(() => {
    const chart = new Yagr(rootRef.current!, buildConfig(themeRef.current, timelineRef.current, valuesRef.current));
    chartRef.current = chart;
    return () => { chart.dispose(); chartRef.current = null; };
  }, []);

  // theme sync
  useEffect(() => {
    const chart = chartRef.current; if (!chart) return;
    chart.setTheme(theme);
    const c = COLORS[theme];
    chart.setSeries(SERIES_ID, {lineColor: c.line, color: c.fill});
    chart.redraw(true, true);
  }, [theme]);

  useImperativeHandle(ref, () => ({
    append(times, values) {
      chartRef.current?.setSeries(times, [{id: SERIES_ID, data: values}], {incremental: true, splice: true});
    },
  }), []);

  return <div className="yagr cpu-chart" ref={rootRef} />;
});
