  box-shadow: 0 8px 20px rgba(0, 0, 0, 0.12);
  padding: 8px 12px;
}

.g-root_theme_dark .yagr-tooltip {
  background: #2d2c33;
  color: rgba(255, 255, 255, 0.85);
  border-color: rgba(255, 255, 255, 0.12);
  box-shadow: 0 8px 20px rgba(0, 0, 0, 0.45);
}

.cpu-tooltip__time {
  font-weight: 600;
